func writeFile(t *testing.T, path, content string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

report.text:
const SchemaVersion = 1

// Bounds on what one report may carry.
const (
	MaxRoles = 32
	// MaxTasks keeps identity pins within the existing 64 KiB host RPC frame.
	MaxTasks = 128
	// MaxCPUCores bounds a role's measured CPU use; no OCI shape exceeds it.
	MaxCPUCores = 1024
	// MaxMemoryBytes bounds a role's measured memory use.
	MaxMemoryBytes = 1 << 44
	// MaxFilesystems allows the host roots and one volume per managed role.
	MaxFilesystems     = MaxRoles + 5
	MaxFilesystemBytes = 1 << 50
	// MaxNetworkBps bounds a host's receive or transmit rate: 1 TiB/s.
	MaxNetworkBps = 1 << 40
	// MaxLoad1 bounds the one-minute load average; the kernel's PID limit
	// keeps real values far below it.
	MaxLoad1 = 1e6
)

var ErrInvalidReport = errors.New("invalid host load report")

var roleRE = regexp.MustCompile(`^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$`)

// Report is one host's load at the moment it was sampled.
type Report struct {
	SchemaVersion uint64      `json:"schema_version"`
	Host          HostUsage   `json:"host"`
	Roles         []RoleUsage `json:"roles,omitempty"`
}

// HostUsage carries capacity, filesystems and utilization fractions in [0,1].
// A nil field was not measured this interval (for example the first CPU sample,
// which has no earlier counter to diff against).
type HostUsage struct {
	FilesystemsIncomplete bool                           `json:"filesystems_incomplete,omitzero"`
	CPUCores              int                            `json:"cpu_capacity_cores,omitzero"`
	MemoryBytes           uint64                         `json:"memory_capacity_bytes,omitzero"`
	CPU                   *float64                       `json:"cpu_util,omitempty"`
	Memory                *float64                       `json:"mem_util,omitempty"`
	Disk                  *float64                       `json:"disk_util,omitempty"`
	Filesystems           []observability.FilesystemView `json:"filesystems,omitempty"`
	// NetworkRxBps and NetworkTxBps are bytes per second over every
	// non-loopback interface since the previous sample; Load1 is the
	// one-minute load average.
	NetworkRxBps *float64 `json:"net_rx_bps,omitempty"`
	NetworkTxBps *float64 `json:"net_tx_bps,omitempty"`
	Load1        *float64 `json:"load1,omitempty"`
}

// RoleUsage is one role's cgroup v2 usage in absolute units, so the
// controller can relate it to the role's signed resource request, plus the
// TerraBase load block when the role is a TerraBase member that reports one.
// Executor roles sum every current local task; partial sums remain unknown.
type RoleUsage struct {
	Role        string                    `json:"role"`
	Tasks       []TaskPin                 `json:"tasks,omitempty"`
	CPUCores    *float64                  `json:"cpu_cores,omitempty"`
	MemoryBytes *uint64                   `json:"memory_bytes,omitempty"`
	CPULimit    *float64                  `json:"cpu_limit_cores,omitempty"`
	MemoryLimit *uint64                   `json:"memory_limit_bytes,omitempty"`
	LimitsRead  bool                      `json:"limits_read,omitzero"`
	TerraBase   *memberstatus.Load        `json:"terrabase,omitempty"`
	WAN         *terrabase.WANObservation `json:"wan,omitempty"`
}

// TaskPin identifies one sampled executor assignment. The manager independently
// authenticates this exact set and its resources; reported pins grant nothing.
type TaskPin struct {
	TaskID      string `json:"task_id"`
	ServiceID   string `json:"service_id"`
	NodeID      string `json:"node_id"`
	Fingerprint string `json:"fingerprint"`
}

func (r Report) Validate() error {
	if r.SchemaVersion != SchemaVersion {
		return fmt.Errorf("%w: schema version %d", ErrInvalidReport, r.SchemaVersion)
	}
	if r.Host.CPUCores < 0 || r.Host.CPUCores > MaxCPUCores || r.Host.MemoryBytes > MaxMemoryBytes {
		return fmt.Errorf("%w: host capacity out of range", ErrInvalidReport)
	}
	for _, value := range []*float64{r.Host.CPU, r.Host.Memory, r.Host.Disk} {
		if value != nil && !fraction(*value) {
			return fmt.Errorf("%w: host utilization out of range", ErrInvalidReport)
		}
	}
	for _, value := range []*float64{r.Host.NetworkRxBps, r.Host.NetworkTxBps} {
		if value != nil && !finiteWithin(*value, MaxNetworkBps) {
			return fmt.Errorf("%w: host network rate out of range", ErrInvalidReport)
		}
	}
	if r.Host.Load1 != nil && !finiteWithin(*r.Host.Load1, MaxLoad1) {
		return fmt.Errorf("%w: host load out of range", ErrInvalidReport)
	}
	if len(r.Host.Filesystems) > MaxFilesystems {
		return fmt.Errorf("%w: more than %d filesystems", ErrInvalidReport, MaxFilesystems)
	}
	filesystems := make(map[string]bool, len(r.Host.Filesystems))
	for _, filesystem := range r.Host.Filesystems {
		if !validFilesystem(filesystem) || filesystems[filesystem.Role] {
			return fmt.Errorf("%w: invalid or repeated filesystem role %q", ErrInvalidReport, filesystem.Role)
		}
		filesystems[filesystem.Role] = true
	}
	if len(r.Roles) > MaxRoles {
		return fmt.Errorf("%w: more than %d roles", ErrInvalidReport, MaxRoles)
	}
	seen := make(map[string]struct{}, len(r.Roles))
	tasks := make(map[string]struct{})
	for _, role := range r.Roles {
		if !roleRE.MatchString(role.Role) {
			return fmt.Errorf("%w: role token", ErrInvalidReport)
		}
		if _, repeated := seen[role.Role]; repeated {
			return fmt.Errorf("%w: repeated role %q", ErrInvalidReport, role.Role)
		}
		seen[role.Role] = struct{}{}
		for _, task := range role.Tasks {
			if !validTaskID(task.TaskID) || !validTaskID(task.ServiceID) || !validTaskID(task.NodeID) ||
				len(task.Fingerprint) != 64 || strings.IndexFunc(task.Fingerprint, func(r rune) bool {
				return !(r >= '0' && r <= '9' || r >= 'a' && r <= 'f')
			}) >= 0 {
				return fmt.Errorf("%w: invalid task identity pin", ErrInvalidReport)
			}
			if _, repeated := tasks[task.TaskID]; repeated {
				return fmt.Errorf("%w: repeated task identity pin", ErrInvalidReport)
			}
			tasks[task.TaskID] = struct{}{}
			if len(tasks) > MaxTasks {
				return fmt.Errorf("%w: more than %d task identity pins", ErrInvalidReport, MaxTasks)
			}
		}
		if role.CPUCores != nil && !finiteWithin(*role.CPUCores, MaxCPUCores) {
			return fmt.Errorf("%w: role %q CPU out of range", ErrInvalidReport, role.Role)
		}
		if role.MemoryBytes != nil && *role.MemoryBytes > MaxMemoryBytes {
			return fmt.Errorf("%w: role %q memory out of range", ErrInvalidReport, role.Role)
		}
		if role.CPULimit != nil && (!finiteWithin(*role.CPULimit, MaxCPUCores) || *role.CPULimit == 0) ||
			role.MemoryLimit != nil && *role.MemoryLimit > MaxMemoryBytes {
			return fmt.Errorf("%w: role limit out of range", ErrInvalidReport)
		}
		if role.TerraBase != nil {
			if err := role.TerraBase.Validate(); err != nil {
				return fmt.Errorf("%w: role %q: %v", ErrInvalidReport, role.Role, err)
			}
		}
		if role.WAN != nil {
			if role.Role != terrabase.Role {
				return fmt.Errorf("%w: WAN observations require the terrabase role", ErrInvalidReport)
			}
			if err := role.WAN.Validate(); err != nil {
				return fmt.Errorf("%w: role %q WAN: %v", ErrInvalidReport, role.Role, err)
			}
		}
	}
	return nil
}

func validTaskID(value string) bool {
	return len(value) > 0 && len(value) <= 64 && strings.IndexFunc(value, func(r rune) bool {
		return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9')
	}) < 0
}

func validFilesystem(filesystem observability.FilesystemView) bool {
	return protocol.ValidateSubjectToken(filesystem.Role) == nil &&
		len(filesystem.Path) <= 4096 && utf8.ValidString(filesystem.Path) &&
		filepath.IsAbs(filesystem.Path) && filepath.Clean(filesystem.Path) == filesystem.Path &&
		!strings.ContainsFunc(filesystem.Path, unicode.IsControl) &&
		filesystem.SizeBytes > 0 && filesystem.SizeBytes <= MaxFilesystemBytes &&
		filesystem.AvailBytes <= filesystem.FreeBytes && filesystem.FreeBytes <= filesystem.SizeBytes &&
		filesystem.Files <= MaxFilesystemBytes && filesystem.FilesFree <= filesystem.Files
}

func fraction(value float64) bool { return finiteWithin(value, 1) }

func finiteWithin(value, limit float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0) && value >= 0 && value <= limit
}

aggregate.text:
func (r run) covered(now time.Time, window, warmUp, minInterval time.Duration) bool {
	allowed := max(window/2, 2*minInterval)
	if now.Sub(r.since) < warmUp || now.Sub(r.last) > allowed {
		return false
	}
	for i := len(r.holes) - 1; i >= 0 && now.Sub(r.holes[i].end) < window; i-- {
		if r.holes[i].length > allowed {
			return false
		}
	}
	return true
}

func (a *Aggregator) Reset() {
	a.mu.Lock()
	clear(a.nodes)
	clear(a.runs)
	a.mu.Unlock()
}

func NewAggregator(config AggregatorConfig) *Aggregator {
	if config.MinInterval <= 0 {
		config.MinInterval = DefaultMinInterval
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = DefaultStaleAfter
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	config.Requests = maps.Clone(config.Requests)
	return &Aggregator{config: config, nodes: make(map[string]*nodeState), runs: make(map[seriesKey]run)}
}

// SetRequests replaces the per-role resource requests, for example after a
// cell spec amendment. Samples already recorded keep the request they were
// computed with.
func (a *Aggregator) SetRequests(requests map[string]Request) {
	a.mu.Lock()
	a.config.Requests = maps.Clone(requests)
	a.mu.Unlock()
}

// nodePoints bounds one node's series: one accepted sample per MinInterval
// over the retention, plus slack.
func (a *Aggregator) nodePoints() int {
	return int(min(nodeRetention/a.config.MinInterval+16, 4096))
}

func (a *Aggregator) Read(ctx context.Context, target autoscale.Target, signal autoscale.Signal, now time.Time) (autoscale.Reading, error) {
	reading := autoscale.Reading{Signal: signal.Name}
	a.mu.Lock()
	// Warm once the run started within one minimum report interval of the
	// window's start, so a window is covered even if its first sample
	// landed a moment after the window opened; but never sooner than one
	// minimum interval, so a window as short as the report interval still
	// needs more than the first report after a reset.
	current, ok := a.runs[seriesKey{target: target, signal: signal.Name}]
	warmUp := max(signal.Window()-a.config.MinInterval, a.config.MinInterval)
	if !ok || now.Sub(current.last) > a.config.StaleAfter ||
		!current.covered(now, signal.Window(), warmUp, a.config.MinInterval) {
		a.mu.Unlock()
		return reading, nil
	}
	a.pruneLocked(a.config.Now(), nodeRetention)
	key := seriesKey{target: target, signal: signal.Name}
	stores := make([]*autoscale.WindowStore, 0, len(a.nodes))
	for _, node := range a.nodes {
		if last, ok := node.series[key]; ok && now.Sub(last) <= a.config.StaleAfter {
			stores = append(stores, node.store)
		}
	}
	a.mu.Unlock()
	values := make([]float64, 0, len(stores))
	for _, store := range stores {
		node, err := store.Read(ctx, target, signal, now)
		if err != nil {
			return autoscale.Reading{}, err
		}
		if node.Samples > 0 {
			values = append(values, node.Value)
			reading.Samples += node.Samples
		}
	}
	reading.Value = autoscale.Aggregate(signal.AggregationOrDefault(), values)
	return reading, nil
}

// Record accepts one validated report. The caller must already have
// authenticated the host and filtered Roles to roles it currently runs.
func (a *Aggregator) Record(origin Origin, report Report) error {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.record(origin, report, a.config.Requests)
}

// RecordRequests normalizes one authenticated host against its actual summed
// task reservations. Other hosts keep their own requests and sample windows.
func (a *Aggregator) RecordRequests(origin Origin, report Report, requests map[string]Request) error {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.record(origin, report, requests)
}

// record is called with the aggregator lock held.
func (a *Aggregator) record(origin Origin, report Report, requests map[string]Request) error {
	if err := report.Validate(); err != nil {
		return err
	}
	now := a.config.Now()
	node, known := a.nodes[origin.Node]
	if known && now.Sub(node.latest.At) < a.config.MinInterval {
		return ErrTooFrequent
	}
	if !known {
		if len(a.nodes) >= maxNodes {
			// Full: forget every node that is no longer reporting, even if
			// a long window could still use its older samples.
			a.pruneLocked(now, a.config.StaleAfter)
		}
		if len(a.nodes) >= maxNodes {
			return ErrTooManyNodes
		}
		node = &nodeState{store: autoscale.NewWindowStore(nodeRetention, a.nodePoints()),
			series: make(map[seriesKey]time.Time)}
		a.nodes[origin.Node] = node
	}
	node.latest = NodeLoad{Origin: origin, At: now, Report: report}
	// Recording under the aggregator lock keeps one node's samples in
	// receive order and its store from being pruned mid-record.
	for _, role := range report.Roles {
		target := autoscale.Target{Cell: origin.Cell, Environment: origin.Environment, Role: role.Role}
		for name, value := range roleSignals(role, report.Host, requests[role.Role]) {
			node.store.Record(target, name, autoscale.Sample{At: now, Value: value})
			key := seriesKey{target: target, signal: name}
			node.series[key] = now
			current := a.runs[key]
			switch gap := now.Sub(current.last); {
			case current.last.IsZero() || gap > a.config.StaleAfter:
				current.since, current.holes = now, nil
			case gap > 2*a.config.MinInterval:
				// Samples arrive in receive order, so holes stay sorted and
				// the expired ones are at the front.
				expired := 0
				for expired < len(current.holes) && now.Sub(current.holes[expired].end) > nodeRetention {
					expired++
				}
				current.holes = append(current.holes[expired:], hole{end: now, length: gap})
			}
			current.last = now
			a.runs[key] = current
		}
	}
	return nil
}

func StatelessSignal(name autoscale.SignalName) bool {
	switch name {
	case autoscale.SignalCPUUtilization, autoscale.SignalMemoryUtilization, autoscale.SignalDiskUtilization:
		return true
	default:
		return false
	}
}

// roleSignals maps one role's usage onto the autoscale signal vocabulary.
// A signal whose input or request is missing is not recorded at all, so
// the autoscaler sees it as unavailable rather than as zero load.
func roleSignals(role RoleUsage, host HostUsage, request Request) map[autoscale.SignalName]float64 {
	signals := make(map[autoscale.SignalName]float64, 7)
	if role.CPUCores != nil && request.CPUCores > 0 {
		signals[autoscale.SignalCPUUtilization] = *role.CPUCores / request.CPUCores
	}
	if role.MemoryBytes != nil && request.MemoryBytes > 0 {
		signals[autoscale.SignalMemoryUtilization] = float64(*role.MemoryBytes) / float64(request.MemoryBytes)
	}
	if host.Disk != nil && (role.CPUCores != nil || role.MemoryBytes != nil) {
		// Disk is shared by every role of the host; it is attributed to the
		// roles that actually run there.
		signals[autoscale.SignalDiskUtilization] = *host.Disk
	}
	if load := role.TerraBase; load != nil {
		signals[autoscale.SignalTerraBaseConnectionsPerMember] = float64(load.Connections)
		signals[autoscale.SignalTerraBaseStorageBytes] = float64(load.StorageBytes)
		signals[autoscale.SignalTerraBaseReplicationLag] = float64(load.ReplicationLagSeq)
		signals[autoscale.SignalTerraBaseWriteQPS] = load.WriteQPS
	}
	return signals
}

// Nodes lists every node's latest report that is not stale, by node name.
func (a *Aggregator) Nodes() []NodeLoad {
	now := a.config.Now()
	a.mu.Lock()
	a.pruneLocked(now, nodeRetention)
	out := make([]NodeLoad, 0, len(a.nodes))
	for _, node := range a.nodes {
		if now.Sub(node.latest.At) <= a.config.StaleAfter {
			out = append(out, node.latest)
		}
	}
	a.mu.Unlock()
	slices.SortFunc(out, func(x, y NodeLoad) int { return strings.Compare(x.Origin.Node, y.Origin.Node) })
	return out
}

// pruneLocked forgets nodes silent for longer than retention; none of their
// samples can fall inside a window any more.
func (a *Aggregator) pruneLocked(now time.Time, retention time.Duration) {
	for name, node := range a.nodes {
		if now.Sub(node.latest.At) > retention {
			delete(a.nodes, name)
		}
	}
	for key, current := range a.runs {
		if now.Sub(current.last) > nodeRetention {
			delete(a.runs, key)
		}
	}
}

window.text:
// WindowStore is an in-memory bounded sample store implementing Source. A
// telemetry consumer records samples and the autoscaler reads windowed
// aggregates. Samples older than retention are discarded on write.
type WindowStore struct {
	mu        sync.Mutex
	retention time.Duration
	maxPoints int
	series    map[seriesKey][]Sample
}

// NewWindowStore bounds every series by age and by point count.
func NewWindowStore(retention time.Duration, maxPoints int) *WindowStore {
	if retention <= 0 {
		// Cover the longest window a valid policy may configure: a shorter
		// retention would silently aggregate only the window's tail.
		retention = time.Duration(maxWindowSeconds) * time.Second
	}
	if maxPoints <= 0 {
		maxPoints = 4096
	}
	return &WindowStore{retention: retention, maxPoints: maxPoints, series: make(map[seriesKey][]Sample)}
}

// Record appends one sample. Non-finite or negative values are dropped.
func (s *WindowStore) Record(target Target, signal SignalName, sample Sample) {
	if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Value < 0 || sample.At.IsZero() {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	key := seriesKey{target: target, signal: signal}
	points := append(s.series[key], sample)
	points = slices.DeleteFunc(points, func(p Sample) bool { return sample.At.Sub(p.At) > s.retention })
	if len(points) > s.maxPoints {
		points = slices.Clone(points[len(points)-s.maxPoints:])
	}
	s.series[key] = points
}

// Read aggregates the samples inside the signal window ending at now.
func (s *WindowStore) Read(_ context.Context, target Target, signal Signal, now time.Time) (Reading, error) {
	s.mu.Lock()
	var values []float64
	for _, point := range s.series[seriesKey{target: target, signal: signal.Name}] {
		if !point.At.After(now) && now.Sub(point.At) <= signal.Window() {
			values = append(values, point.Value)
		}
	}
	s.mu.Unlock()
	return Reading{Signal: signal.Name, Value: Aggregate(signal.AggregationOrDefault(), values), Samples: len(values)}, nil
}

// Aggregate reduces values; an empty input yields zero.
func Aggregate(aggregation Aggregation, values []float64) float64 {
	if len(values) == 0 {
		return 0
	}
	switch aggregation {
	case AggregateMax:
		return slices.Max(values)
	case AggregateP95:
		sorted := slices.Clone(values)
		slices.Sort(sorted)
		index := int(math.Ceil(0.95*float64(len(sorted)))) - 1
		return sorted[max(index, 0)]
	default:
		sum := 0.0
		for _, value := range values {
			sum += value
		}
		return sum / float64(len(values))
	}
}

func (s Signal) Window() time.Duration {
	if s.WindowSeconds == 0 {
		return time.Minute
	}
	return time.Duration(s.WindowSeconds) * time.Second
}

// AggregationOrDefault returns the configured aggregation or the average.
func (s Signal) AggregationOrDefault() Aggregation {
	if s.Aggregation == "" {
		return AggregateAverage
	}
	return s.Aggregation
}

sampler.text:
func NewSampler(config SamplerConfig) *Sampler {
	if config.CgroupMount == "" {
		config.CgroupMount = "/sys/fs/cgroup"
	}
	if config.ReadSystem == nil {
		config.ReadSystem = observability.ReadSystem
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	return &Sampler{config: config, roles: make(map[string]cpuPoint)}
}

func (s *Sampler) Sample(terrabase map[string]memberstatus.Load) Report {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.config.Now()
	report := Report{SchemaVersion: SchemaVersion}
	memTotal := uint64(0)
	if view, err := s.config.ReadSystem(s.config.Filesystems); err == nil {
		memTotal = view.MemTotalBytes
		if view.CPUCount > 0 && view.CPUCount <= MaxCPUCores {
			report.Host.CPUCores = view.CPUCount
		}
		if view.MemTotalBytes <= MaxMemoryBytes {
			report.Host.MemoryBytes = view.MemTotalBytes
		}
		busy := view.CPUSeconds.Busy()
		total := busy + view.CPUSeconds.Idle + view.CPUSeconds.IOWait
		if s.hostSeen && total > s.host.total && busy >= s.host.usage {
			report.Host.CPU = ratio(busy-s.host.usage, total-s.host.total)
		}
		s.host, s.hostSeen = cpuPoint{usage: busy, total: total, at: now}, true
		if view.MemTotalBytes > 0 && view.MemAvailBytes <= view.MemTotalBytes {
			report.Host.Memory = ratio(float64(view.MemTotalBytes-view.MemAvailBytes), float64(view.MemTotalBytes))
		}
		if finiteWithin(view.Load1, MaxLoad1) {
			load := view.Load1
			report.Host.Load1 = &load
		}
		if rx, tx := view.NetRxBytes, view.NetTxBytes; rx > 0 && tx > 0 {
			// A counter that went backwards means the interface reset, so
			// that interval has no valid rate.
			if elapsed := now.Sub(s.net.at).Seconds(); s.net.seen && elapsed > 0 && rx >= s.net.rx && tx >= s.net.tx {
				rxBps := float64(rx-s.net.rx) / elapsed
				txBps := float64(tx-s.net.tx) / elapsed
				if finiteWithin(rxBps, MaxNetworkBps) && finiteWithin(txBps, MaxNetworkBps) {
					report.Host.NetworkRxBps, report.Host.NetworkTxBps = &rxBps, &txBps
				}
			}
			s.net = netPoint{rx: rx, tx: tx, at: now, seen: true}
		}
		seen := make(map[string]bool)
		for _, filesystem := range view.Filesystems {
			if len(report.Host.Filesystems) == MaxFilesystems {
				report.Host.FilesystemsIncomplete = true
				break
			}
			if !validFilesystem(filesystem) || seen[filesystem.Role] {
				report.Host.FilesystemsIncomplete = true
				continue
			}
			seen[filesystem.Role] = true
			report.Host.Filesystems = append(report.Host.Filesystems, filesystem)
			used := ratio(float64(filesystem.SizeBytes-filesystem.AvailBytes), float64(filesystem.SizeBytes))
			if report.Host.Disk == nil || *used > *report.Host.Disk {
				report.Host.Disk = used
			}
		}
	} else {
		report.Host.FilesystemsIncomplete = true
	}
	present := make(map[string]struct{}, len(s.config.Roles))
	for _, role := range s.config.Roles {
		if len(report.Roles) == MaxRoles {
			break
		}
		usage, seen := s.sampleCgroup(role, now, memTotal)
		if seen {
			present[role] = struct{}{}
		}
		if load, ok := terrabase[role]; ok && load.Validate() == nil {
			usage.TerraBase = &load
		}
		if usage.CPUCores != nil || usage.MemoryBytes != nil || usage.TerraBase != nil {
			report.Roles = append(report.Roles, usage)
		}
	}
	// A role whose group vanished (stopped workload) restarts its CPU
	// baseline when it comes back, so a restart never reads as a burst.
	s.forgetCgroups(present)
	return report
}

func (s *Sampler) sampleCgroup(role string, now time.Time, memTotal uint64) (RoleUsage, bool) {
	usage := RoleUsage{Role: role}
	if s.config.CgroupRoot == "" {
		return usage, false
	}
	present := false
	group := filepath.Join(s.config.CgroupRoot, role)
	usage.CPULimit, usage.MemoryLimit, usage.LimitsRead = readLimits(group, s.config.CgroupMount)
	if usage.MemoryLimit != nil && memTotal > 0 {
		limit := min(*usage.MemoryLimit, memTotal)
		usage.MemoryLimit = &limit
	}
	if seconds, identity, ok := readGroupCPUSeconds(group); ok {
		present = true
		previous, seen := s.roles[role]
		// A group recreated between samples (a restart or rollout)
		// has a new identity: its counter restarts the baseline even
		// when it already exceeds the old group's counter.
		sameGroup := seen && os.SameFile(previous.group, identity)
		if elapsed := now.Sub(previous.at).Seconds(); sameGroup && elapsed > 0 && seconds >= previous.usage {
			cores := (seconds - previous.usage) / elapsed
			if finiteWithin(cores, MaxCPUCores) {
				usage.CPUCores = &cores
			}
		}
		s.roles[role] = cpuPoint{usage: seconds, at: now, group: identity}
	}
	if memory, ok := readWorkingSet(group); ok && memory <= MaxMemoryBytes && (memTotal == 0 || memory <= memTotal) {
		usage.MemoryBytes = &memory
	}
	return usage, present
}

func (s *Sampler) forgetCgroups(present map[string]struct{}) {
	for role := range s.roles {
		if _, ok := present[role]; !ok {
			delete(s.roles, role)
		}
	}
}

func ratio(numerator, denominator float64) *float64 {
	value := numerator / denominator
	if !fraction(value) {
		value = min(max(value, 0), 1)
	}
	return &value
}

